-- Study Abroad country content, BATCH 29: Pacific (Kiribati, Marshall Islands, Micronesia, Nauru, Palau, PNG, Samoa, Solomon Islands, Tonga, Tuvalu, Vanuatu).
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('kiribati', 'marshall-islands', 'micronesia', 'nauru', 'palau', 'papua-new-guinea', 'samoa', 'solomon-islands', 'tonga', 'tuvalu', 'vanuatu'));
UPDATE countries SET why_title = 'Why study in Kiribati?', why_body = '<p>Kiribati offers vocational and regional university study through the Kiribati Institute of Technology and the USP campus on Tarawa, in a small Pacific atoll nation.<ul><li>Small campuses</li><li>Kiribati Institute of Technology</li><li>USP Kiribati campus</li><li>Climate and marine studies context</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Kiribati publishes visa enquiries through its immigration division (visaofficer@mfa.gov.ki). The official student visa form (2020) asks whether the study is tertiary, domestic or other; one guide says the permit applies to programmes of more than three months.</p><ul><li>Acceptance letter from the institution</li><li>Evidence of programme, funds, health and character (aggregators)</li><li>Extensions are applied for at the Tarawa immigration office before the visa expires (travel guide)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Kiribati Ministry of Foreign Affairs and Immigration site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution; no 2026 admission details were found.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No fee or visa fee figures were found for 2026.</p><ul><li>Contact USP Kiribati and KIT for fees</li><li>USP is a regional university owned by 12 Pacific countries; students from non-member countries pay the International Student tuition fee (2025 schedule).</li><li>Living costs: about US$500-$900 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'kiribati';
UPDATE countries SET why_title = 'Why study in the Marshall Islands?', why_body = '<p>The Marshall Islands offers a US-style community college and a USP campus in Majuro, in a small Pacific nation with close links to the United States.<ul><li>English-medium teaching</li><li>College of the Marshall Islands</li><li>USP Marshall Islands campus</li><li>US-accredited associate and bachelor''s degrees</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>No authoritative visa source was found. CMI recommends starting six months early, and applicants missing only the student visa and the RMI Social Security Card can be admitted conditionally.</p><ul><li>Admission to CMI with conditional admission possible</li><li>Check the RMI embassy or the US Embassy in Majuro</li><li>One site claims Compact of Free Association visa-free US access; unverified and not relevant to most students</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official RMI embassy and CMI site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>CMI recommends international applicants start about six months before term.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Figures conflict.</p><ul><li>DataUSA 2024 undergraduate tuition: US$4,410; another listing: US$3,500 (in-state) and US$3,720 (out-of-state)</li><li>Appily average net price: US$3,152</li><li>Living costs: about US$800-$1,400 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'marshall-islands';
UPDATE countries SET why_title = 'Why study in Micronesia?', why_body = '<p>The Federated States of Micronesia has the College of Micronesia-FSM, a US-style land-grant college offering associate and bachelor''s degrees across several islands.<ul><li>English-medium teaching</li><li>College of Micronesia-FSM</li><li>Small campuses</li><li>US-style community college system</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>No student-visa information was found in this research. Contact the FSM government or the nearest embassy or consulate.</p><ul><li>Admission letter from the college</li><li>Check the FSM embassy for entry rules</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official FSM government and the college site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to the college.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Published figures conflict.</p><ul><li>DataUSA 2024 median undergraduate tuition: US$4,350; other aggregators US$4,750-$5,050</li><li>The college page lists US$95 per credit adopted in 2006; likely outdated</li><li>Living costs: about US$600-$1,000 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'micronesia';
UPDATE countries SET why_title = 'Why study in Nauru?', why_body = '<p>Nauru does not operate its own higher-education institutions; the only tertiary option is the USP Nauru Campus.<ul><li>USP Nauru Campus</li><li>Regional university owned by 12 Pacific countries</li><li>Very small campus</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Aggregators say a student visa is required before entering Nauru, with coordination through the Nauruan Immigration Department. Confirm with the department or the nearest embassy.</p><ul><li>Admission to USP</li><li>Student visa before travel</li><li>Check the Nauru Immigration Department</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Nauru Immigration Department and USP site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Admission is handled by USP, not by the Nauruan government.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No Nauru-specific fee was found.</p><ul><li>USP is a regional university owned by 12 Pacific countries; students from non-member countries pay the International Student tuition fee (2025 schedule).</li><li>An aggregator claims AUD 1,000-3,000 a year for public universities; unreliable because Nauru has no public university</li><li>Living costs: about US$700-$1,200 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'nauru';
UPDATE countries SET why_title = 'Why study in Palau?', why_body = '<p>Palau offers US-style associate and short-course study at Palau Community College on the island of Koror, in a Pacific nation known for marine conservation.<ul><li>English-medium teaching</li><li>Palau Community College</li><li>Marine and environmental focus</li><li>Small campus</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A Student Visa is for full-time students who live in school-maintained housing. Student Visa holders may not work unless the Director of Immigration exempts them in writing, and there is no listed post-study work visa.</p><ul><li>Admission letter from the college</li><li>Student visa typically through immigration or the admitting institution</li><li>Check the Palau Division of Immigration</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Palau Division of Immigration and Palau Community College site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to the college.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Estimates vary.</p><ul><li>Non-resident tuition: US$140 per credit (about US$1,680 per 12-credit semester) plus fees, housing and board (2024-2028 catalog, per a guide)</li><li>IPEDS-based 2024-25 out-of-state tuition: about US$3,360</li><li>Scholarships of US$500 per student for an academic year were reported; unverified</li><li>Living costs: about US$800-$1,400 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'palau';
UPDATE countries SET why_title = 'Why study in Papua New Guinea?', why_body = '<p>Papua New Guinea has English-medium universities such as UPNG, Unitech and Divine Word University, with a separate, lower fee band for South Pacific students.<ul><li>English-medium teaching</li><li>University of Papua New Guinea</li><li>Strengths in mining, agriculture, health and law</li><li>Separate fee band for South Pacific students</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>No student-visa information was found in this research; contact the PNG Immigration and Citizenship Authority or the nearest PNG embassy.</p><ul><li>Admission letter from the university</li><li>New UPNG students must pay compulsory fees online by 2 February 2026 to keep their place</li><li>Check the PNG Immigration and Citizenship Authority</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official PNG Immigration and Citizenship Authority and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university; UPNG''s School of Business and Public Policy accepted 2027 Bachelor of Economics (Honours) applications until 27 November 2026.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>UPNG publishes separate fees for South Pacific and other international students.</p><ul><li>UPNG 2026 Medicine and Health Sciences: K12,970 (South Pacific) and K26,930 (other international); check the full PDF for other programmes</li><li>UPNG raised fees for 2027</li><li>A US$5,000 women''s scholarship listing for international students (deadline 28 August 2026) is from an aggregator; verify</li><li>Living costs: about US$700-$1,200 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'papua-new-guinea';
UPDATE countries SET why_title = 'Why study in Samoa?', why_body = '<p>Samoa offers English-medium study at the National University of Samoa and a USP campus at Alafua, plus the Oceania University of Medicine.<ul><li>English-medium teaching</li><li>National University of Samoa</li><li>USP Alafua campus</li><li>Oceania University of Medicine</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Study needs a pre-arrival <strong>Temporary Resident Permit</strong> from Samoa Immigration (MPMC), reported at SAT 450 (2026). An offer of place does not guarantee a Study Permit.</p><ul><li>Offer of place from an institution</li><li>Permit approved before you travel</li><li>Part-time work only if Samoa Immigration authorises it</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Samoa Immigration (MPMC) and your institution site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>NUS does not publish international tuition online; ask the International Office for a written quote.</p><ul><li>An aggregator lists about US$10,000 for international students; unverified</li><li>NUS scholarships page lists awards from outside funders, none for international students coming to Samoa</li><li>USP is a regional university owned by 12 Pacific countries; students from non-member countries pay the International Student tuition fee (2025 schedule).</li><li>Living costs: about US$600-$1,000 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'samoa';
UPDATE countries SET why_title = 'Why study in the Solomon Islands?', why_body = '<p>The Solomon Islands offers study at Solomon Islands National University (SINU) and a USP campus in Honiara, with English requirements for some programmes.<ul><li>English-medium teaching</li><li>Solomon Islands National University</li><li>USP campus in Honiara</li><li>Strengths in education, health and natural resources</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Apply for a student visa before travel through the immigration department or the accepting institution; no official 2026 checklist was found.</p><ul><li>Admission letter from the institution</li><li>Aggregator visa fee: US$450 plus a US$50 online fee; unverified</li><li>Check the Solomon Islands immigration channels</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Solomon Islands immigration and SINU site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>SINU 2026 applications opened in 2025; a completed English Form 6 score of 4 or better, or a basic English entry exam, is required for some programmes.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Sources disagree.</p><ul><li>uniRank: US$1,000-$2,499 a year for international undergraduates</li><li>University.im: SBD 5,000-15,000 a year for public universities; another source lists SINU at EUR 2,500 (unreliable)</li><li>Living costs: about US$500-$900 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'solomon-islands';
UPDATE countries SET why_title = 'Why study in Tonga?', why_body = '<p>Tonga offers study at Tonga National University and the USP Tonga campus in a Polynesian kingdom.<ul><li>English-medium teaching</li><li>Tonga National University</li><li>USP Tonga campus</li><li>Australia Awards support for citizens</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>No 2026 Tonga student visa rules were found in this research. Confirm with Tonga immigration and the university.</p><ul><li>Admission letter from the institution</li><li>Check Tonga immigration</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Tonga immigration and your institution site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>TNU''s 2026 application closed on 6 February 2026; check the site for 2027 intake details.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>International rates were not confirmed.</p><ul><li>TNU council approved a 10% tuition increase from January 2026; the international rate was to be proposed to a later council meeting</li><li>Public tertiary education is not tuition-free under Tongan policy</li><li>USP is a regional university owned by 12 Pacific countries; students from non-member countries pay the International Student tuition fee (2025 schedule).</li><li>Living costs: about US$600-$1,000 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'tonga';
UPDATE countries SET why_title = 'Why study in Tuvalu?', why_body = '<p>Tuvalu has one tertiary campus, the USP Tuvalu campus, and a maritime training institute, in one of the world''s smallest and most climate-exposed nations.<ul><li>USP Tuvalu campus</li><li>Tuvalu Maritime Training Institute</li><li>Climate and ocean context</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Sources agree a student visa is needed, arranged through the Tuvalu Immigration Department or the accepting institution. With limited consular presence, check requirements with the department.</p><ul><li>Admission letter from USP or the institute</li><li>Check the Tuvalu Immigration Department</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Tuvalu Immigration Department and USP site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Contact the USP Tuvalu campus office.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No official Tuvalu campus fee schedule was found.</p><ul><li>USP is a regional university owned by 12 Pacific countries; students from non-member countries pay the International Student tuition fee (2025 schedule).</li><li>An aggregator claims AUD 1,000-3,000 a year; unverified</li><li>Living costs: about US$700-$1,200 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'tuvalu';
UPDATE countries SET why_title = 'Why study in Vanuatu?', why_body = '<p>Vanuatu hosts the USP Emalus Campus in Port Vila, with English-medium programmes, in a Melanesian island nation.<ul><li>English-medium teaching</li><li>USP Emalus Campus</li><li>Law school at Emalus</li><li>On-campus accommodation</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Foreign students need a <strong>Student Visa</strong> from the Department of Immigration and Passport Services, applied for from outside Vanuatu even if your passport allows visa-free visits. It is valid for the study period (one page says up to one year).</p><ul><li>Admission letter from USP or another institution</li><li>Holders must not work or run a business unless related to their programme</li><li>No post-study work route listed</li><li>Visa status cannot be changed</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Vanuatu Department of Immigration and Passport Services and USP site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to USP.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof for non-native speakers</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Only the 2025 USP schedule was official.</p><ul><li>USP 2025 schedule has an Emalus column in vatu; non-member citizens pay the International Student fee</li><li>A guide lists FJ$18,000 a year for a bachelor''s and VT635,840 a year for a full-time master''s in 2026; unconfirmed on a USP page</li><li>Australia Awards support Vanuatu citizens only</li><li>Living costs: about US$700-$1,200 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'vanuatu';
COMMIT;
